        this.id = '';
        this.innerHTML = '';
        this.textContent = '';
        this.offsetWidth = 272;
        this.offsetHeight = 0;
        this.clientHeight = 0;
        this.scrollHeight = 0;
        this.offsetTop = 0;
        this.value = '';
    }

    appendChild(child) {
        this.children.push(child);
        child.parentElement = this;
        this._recomputeLayout();
        return child;
