        const idx = this.children.indexOf(child);
        if (idx !== -1) {
            this.children.splice(idx, 1);
            child.parentElement = null;
        }
        this._recomputeLayout();
        return child;
    }

    insertBefore(newChild, refChild) {
        const idx = this.children.indexOf(refChild);
        if (idx !== -1) {
            this.children.splice(idx, 0, newChild);
        } else {
            this.children.push(newChild);
        }
        newChild.parentElement = this;
        this._recomputeLayout();
        return newChild;
    }

    getAttribute(name) { return this.attributes[name] || null; }
    setAttribute(name, val) { this.attributes[name] = String(val); }
    hasAttribute(name) { return name in this.attributes; }
    removeAttribute(name) { delete this.attributes[name]; }

    querySelector(sel) {
        return this.querySelectorAll(sel)[0] || null;
    }

    querySelectorAll(sel) {
        const res = [];
        const match = (node) => {
            let matched = false;
            if (sel.startsWith('.') && node.className && node.className.split(/\\s+/).includes(sel.slice(1))) matched = true;
            else if (sel.startsWith('#') && node.id === sel.slice(1)) matched = true;
            else if (sel.toUpperCase() === node.tagName) matched = true;
            else if (sel.includes('.')) {
                const parts = sel.split('.');
                if ((!parts[0] || parts[0].toUpperCase() === node.tagName) && node.className && node.className.includes(parts[1])) matched = true;
            }
            if (matched) res.push(node);
            for (const c of node.children) match(c);
        };
        for (const c of this.children) match(c);
        return res;
    }

    get lastElementChild() {
        for (let i = this.children.length - 1; i >= 0; i--) {
            if (this.children[i].tagName) return this.children[i];
        }
        return null;
    }

    get firstElementChild() {
        for (let i = 0; i < this.children.length; i++) {
            if (this.children[i].tagName) return this.children[i];
        }
        return null;
    }

    closest(sel) {
        let cur = this;
        while (cur) {
            if (sel.startsWith('.') && cur.className && cur.className.includes(sel.slice(1))) return cur;
            if (sel.startsWith('#') && cur.id === sel.slice(1)) return cur;
            if (sel.toUpperCase() === cur.tagName) return cur;
            cur = cur.parentElement;
        }
        return null;
    }

    getBoundingClientRect() {
        return {
            top: this.offsetTop,
            bottom: this.offsetTop + this.offsetHeight,
            left: 0,
            right: this.offsetWidth,
            width: this.offsetWidth,
            height: this.offsetHeight
        };
    }

    _recomputeLayout() {
        // Calculate realistic heights based on element type
        let h = 0;
        const fontName = currentFont;
