            const m = this.className.match(/title-level-(\\d+)/);
            const lvl = m ? parseInt(m[1]) : 3;
            const headingSizes = { 0: 34, 1: 50, 2: 24, 3: 18, 4: 16, 5: 15, 6: 14, 7: 12 };
            const hSize = headingSizes[lvl] || 16;
            const mt = parseFloat(this.style.marginTop) || (lvl <= 2 ? 16 : 8);
            const mb = parseFloat(this.style.marginBottom) || (lvl <= 2 ? 14 : 6);
            h = Math.round(hSize * 1.3 + mt + mb);
        } else if (this.className.includes('block-h3-span')) {
            h = 42; // Span heading
        } else if (this.className.includes('sec-divider-wrap')) {
            h = 44;
        } else if (this.className.includes('top-header-grid')) {
            h = 30;
        } else if (this.className.includes('page-number-footer')) {
            h = 24;
        } else if (this.className.includes('footnote-area')) {
            // Count note lines inside
            const noteLines = this.querySelectorAll('.note-line');
            const n = Math.max(1, noteLines.length);
            h = Math.round(n * 16 + 24);
        } else if (this.className.includes('main-column')) {
            // Sum of children heights
            let totalH = 0;
            for (const c of this.children) {
                totalH += c.offsetHeight;
            }
            h = totalH;
        } else if (this.className.includes('block-2col')) {
            const rCol = this.querySelector('.right-col');
            const lCol = this.querySelector('.left-col');
            const rH = rCol ? rCol.offsetHeight : 0;
            const lH = lCol ? lCol.offsetHeight : 0;
            h = Math.max(rH, lH);
        } else if (this.className.includes('page-body-flow')) {
            let totalH = 0;
            for (const c of this.children) {
                totalH += c.offsetHeight;
            }
            h = totalH;
        } else if (this.className.includes('page-content-wrapper')) {
            h = 1009;
        } else if (this.className.includes('a4-page')) {
            h = 1122;
        }

        this.offsetHeight = h;
        this.scrollHeight = h;
        this.clientHeight = h;
    }
}

console.log("DOM layout simulator created successfully!");
"""

